nextflow_process {

    name "Test Process SCANPY_PCA"
    script "../main.nf"
    process "SCANPY_PCA"

    tag "modules"
    tag "modules_nfcore"
    tag "scanpy"
    tag "scanpy/pca"

    // params.modules_testdata_base_path is null outside the process string, so use the same env var and default as tests/config/nf-test.config
    def modules_testdata_base_path = System.getenv('NXF_MODULES_TESTDATA_BASE') ?: 'https://raw.githubusercontent.com/nf-core/test-datasets/modules/data/'

    test("Should emit zarr output for zarr input - stub") {

        options '-stub'

        when {
            process {
                """
                input[0] = [ [ id: 'test_zarr' ], file('test.zarr') ]
                input[1] = "X_pca"
                """
            }
        }

        then {
            assertAll(
            { assert process.success },
            { assert process.out.anndata },
            { assert file(process.out.anndata[0][1]).name == "test_zarr_pca.zarr" }
            )
        }

    }

    test("Should run with zarr input") {

        def zarr
        setup {
            zarr = extract(modules_testdata_base_path + 'genomics/homo_sapiens/scrnaseq/zarr/test_zarr.zarr.tar.gz').resolve('test.zarr')
        }

        when {
            process {
                """
                input[0] = [ [ id: 'test_zarr' ], file('${zarr}') ]
                input[1] = "X_pca"
                """
            }
        }

        then {
            assertAll(
            { assert process.success },
            { assert process.out.anndata },
            { assert file(process.out.anndata[0][1]).name == "test_zarr_pca.zarr" },
            { assert file(process.out.anndata[0][1] + "/obsm/X_pca/.zarray").exists() },
            { assert file(process.out.obsm[0][1]).name == "X_test_zarr_pca.pkl" }
            )
        }

    }

    test("Should run without failures") {

        when {
            process {
                """
                input[0] = Channel.of([
                        [ id: 'test' ],
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/scrnaseq/h5ad/combined_filtered_matrix.h5ad', checkIfExists: true)
                    ]
                )
                input[1] = "X_pca"
                """
            }
        }

        then {
            assertAll(
            { assert process.success },
            { assert process.out.anndata },
            { assert file(process.out.anndata[0][1]).name == "test_pca.h5ad" },
            { assert process.out.obsm },
            { assert file(process.out.obsm[0][1]).name == "X_test_pca.pkl" },
            { assert process.out.versions },
            { assert "X_pca" in anndata(process.out.anndata[0][1]).obsm }
            )
        }

    }

    test("Should run without failures - stub") {

        options '-stub'

        when {
            process {
                """
                input[0] = Channel.of([
                        [ id: 'test' ],
                        file(params.modules_testdata_base_path + 'genomics/homo_sapiens/scrnaseq/h5ad/combined_filtered_matrix.h5ad', checkIfExists: true)
                    ]
                )
                input[1] = "X_pca"
                """
            }
        }

        then {
            assertAll(
            { assert process.success },
            { assert snapshot(process.out).match() }
            )
        }

    }

}
